solution:
function rotatedIndex(ids: number[], target: number): number {
  let lo = 0, hi = ids.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (ids[mid] === target) return mid;
    if (ids[lo] <= ids[mid]) {
      if (ids[lo] <= target && target < ids[mid]) hi = mid - 1; else lo = mid + 1;
    } else {
      if (ids[mid] < target && target <= ids[hi]) lo = mid + 1; else hi = mid - 1;
    }
  }
  return -1;
}
